import { IconCheckCircle, IconSync } from "@airbus/icons";
import { svgColor, svgUri } from "../../helpers";
import { StyleFn } from "..";

export const Autosave: StyleFn = (theme, mode) => {
  const { font, size, color } = theme;
  const textColor = color.text.neutral.strong[mode];
  const successColor = color.text.feedback.success.default[mode];

  return {
    "@keyframes rotate": {
      to: { transform: "rotate(-360deg)" },
    },
    root: {
      display: "flex",
      alignItems: "center",
      height: size.spacing[32],
      padding: size.spacing[8],
      paddingLeft: size.spacing[32],
      fontSize: font.size.medium,
      fontWeight: font.weight.bold,
      color: textColor,
      position: "relative",
      cursor: "default",
      "&:before": {
        position: "absolute",
        content: "''",
        width: size.spacing[24],
        height: size.spacing[24],
        top: size.spacing[4],
        left: 0,
        transformOrigin: "0.71875rem center",
        backgroundImage: svgUri(
          svgColor(IconSync.data, textColor)
        ),
        backgroundSize: "100%",
      },
    },
    _progress: {
      "&:before": {
        animation: "$rotate 1s linear infinite",
      },
    },
    _success: {
      color: successColor,
      "&:before": {
        backgroundImage: svgUri(
          svgColor(IconCheckCircle.data, successColor)
        ),
      },
    },
    _small: {
      height: size.spacing[24],
      paddingLeft: size.spacing[24],
      fontSize: font.size.small,
      "&:before": {
        width: size.spacing[16],
        height: size.spacing[16],
        transformOrigin: "0.46875rem center",
      },
    },
  };
};
